parameters.functionScript:
// From the file's own name: Office files only download; everything else in Hand-in kinds can be shown.
if (Inputs.kinds === undefined) return;
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const name = String(Inputs.fileName || '');
const dot = name.lastIndexOf('.');
const ext = dot > 0 ? name.slice(dot + 1).toLowerCase() : '';
const row = (Inputs.kinds || []).find((k) => ext && get(k, 'ext') === ext);
const can = !!row && get(row, 'preview') !== 'none';
const showing = Inputs.showing === true;
Outputs.showOpen = can && !showing;
Outputs.showHide = can && showing;
Outputs.cantShow = !can;

/*
 * Shows a stored file inside this part, never as a page of its own (PLATFORM.md feature 5).
 * HTML only in an iframe sandboxed to allow-scripts: an opaque origin, no cookies, storage or
 * parent. Never allow-same-origin. PDFs in a plain frame (Chrome's viewer does not run in a
 * sandbox; handIn has checked the bytes really are a PDF); images, audio and video in their
 * own elements. The link is minted now by the function that checks who may have it, lasts
 * 5 minutes and is never stored.
 */
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const host = Inputs.host && typeof Inputs.host.getDOMElement === 'function' ? Inputs.host.getDOMElement() : null;
const name = String(Inputs.fileName || '');
const dot = name.lastIndexOf('.');
const ext = dot > 0 ? name.slice(dot + 1).toLowerCase() : '';
const row = (Inputs.kinds || []).find((k) => ext && get(k, 'ext') === ext);
const preview = row ? get(row, 'preview') : 'none';
const FUNCTIONS = { own: 'fileLink', coach: 'fileLinkAsCoach', resource: 'resourceLink' };
const fn = FUNCTIONS[Inputs.mode];
if (!host || !Inputs.file || !fn || preview === 'none') return;
const params = Inputs.mode === 'resource'
  ? { stepId: String(Inputs.stepId || ''), file: String(Inputs.file) }
  : { name: String(Inputs.file) };
(async () => {
  try {
    const answer = await Noodl.CloudFunctions.run(fn, params);
    const base = String((Noodl.getMetaData('cloudservices') || {}).endpoint || '').replace(/\/+$/, '');
    let el;
    if (preview === 'image') {
      el = document.createElement('img');
      el.alt = name;
      el.style.cssText = 'display:block;max-width:100%;height:auto;border:1px solid var(--border);border-radius:var(--radius-md)';
    } else if (preview === 'audio' || preview === 'video') {
      el = document.createElement(preview);
      el.controls = true;
      el.preload = 'metadata';
      el.style.cssText = preview === 'video'
        ? 'display:block;width:100%;max-height:70vh;background:var(--foreground);border-radius:var(--radius-md)'
        : 'display:block;width:100%';
    } else {
      el = document.createElement('iframe');
      if (preview === 'sandbox') el.setAttribute('sandbox', 'allow-scripts');
      el.title = name;
      el.referrerPolicy = 'no-referrer';
      el.style.cssText = 'display:block;width:100%;height:min(70vh,720px);border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface)';
    }
    el.setAttribute('data-testid', 'file-preview');
    el.src = base + answer.url;
    host.replaceChildren(el);
    Outputs.done();
  } catch (e) {
    console.error('[dbu:File viewer]', (e && e.error) || e);
    Outputs.failed();
  }
})();

/*
 * A plain link would save the stored name (<16 hex>_essay.docx) and could open an HTML file
 * as a page on the backend's origin (PLATFORM.md D2, D5). So: fetch the bytes through a
 * fresh signed link, then hand them over as a download under the file's own name.
 */
const FUNCTIONS = { own: 'fileLink', coach: 'fileLinkAsCoach', resource: 'resourceLink' };
const fn = FUNCTIONS[Inputs.mode];
const name = String(Inputs.fileName || 'file');
if (!Inputs.file || !fn) return;
const params = Inputs.mode === 'resource'
  ? { stepId: String(Inputs.stepId || ''), file: String(Inputs.file) }
  : { name: String(Inputs.file) };
(async () => {
  try {
    const answer = await Noodl.CloudFunctions.run(fn, params);
    const base = String((Noodl.getMetaData('cloudservices') || {}).endpoint || '').replace(/\/+$/, '');
    const res = await fetch(base + answer.url);
    if (!res.ok) throw new Error('download answered ' + res.status);
    const blob = new Blob([await res.blob()], { type: 'application/octet-stream' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (e) {
    console.error('[dbu:File viewer download]', (e && e.error) || e);
    Outputs.failed();
  }
})();
